    'landing.sol_1_title': 'E-posta yakala + ayıkla',
    'landing.sol_1_desc':
      'IMAP ile gelen kutusu taranır. AI (Claude) e-postayı ayrıştırır: müşteri, parça kodları, miktarlar, aciliyet. Düşük güvenli sonuçlar insan onayına sunulur.',
    'landing.sol_2_title': 'Parça eşleştir + teklif hazırla',
    'landing.sol_2_desc':
      '4000+ parçalık katalogda fuzzy eşleştirme. Kod, isim, semantik benzerlik ile en yakın parçalar bulunur. Fiyat otomatik çekilir, teklif taslağı oluşur.',
    'landing.sol_3_title': 'Onayla + PDF + gönder + izle',
    'landing.sol_3_desc':
      'Yönetici onaylar, profesyonel PDF üretilir, müşteri e-postası tek tıkla gönderilir. Her adım denetim izinde. Bildirimler anlık.',
    'landing.solution_ai_title': 'AI öneride bulunur, insan karar verir.',
    'landing.solution_ai_body':
      'Parça eşleştirme ve kategori tahmini AI desteklidir. Ancak her öneri güven skoru ile sunulur ve düşük güvenli sonuçlar otomatik olarak insan incelemesine yönlendirilir. Hiçbir işlem otomatik onaylanmaz.',

