    'landing.faq_label': 'SSS',
    'landing.faq_title': 'Sık sorulan sorular',
    'landing.faq_q1': 'E-postalarımız güvende mi?',
    'landing.faq_a1':
      'Evet. E-posta şifreleri Fernet (AES-256) ile şifrelenir. IMAP bağlantısı SSL/TLS üzerinden yapılır. Tüm veriler PostgreSQL’de saklanır, erişim RBAC ile kontrol edilir. Denetim izi (audit trail) her işlemi kayıt altına alır.',
    'landing.faq_q2': 'AI yanlış yaparsa ne olur?',
    'landing.faq_a2':
      'AI (Claude) her ayrıştırma sonucunu bir güven skoru ile sunar. Düşük güvenli sonuçlar (%75 altı) otomatik olarak insan incelemesine yönlendirilir. Hiçbir işlem otomatik onaylanmaz — her zaman bir insan karar verir. Hatalı sonuçları düzeltebilir ve sistem bu düzeltmelerden öğrenir.',
    'landing.faq_q3': 'Kurulum ne kadar sürer?',
    'landing.faq_a3':
      'Tipik kurulum 1 iş günü. E-posta bağlantısı, parça kataloğu ve fiyat listesi yüklendikten sonra sistem kullanıma hazır. Ekibinize rehberli eğitim dahil.',
    'landing.faq_q4': 'Mevcut sürecimiz bozulur mu?',
    'landing.faq_a4':
      'Hayır. Sistem mevcut e-posta akışınızın yanına eklenir — hiçbir şeyi değiştirmez. Gelen kutunuz aynen çalışır, sistem sadece kopyaları okur (salt okunur IMAP). Kademeli geçiş için özellik bayrağı desteği vardır.',
    'landing.faq_q5': 'Onay ve yetkilendirme nasıl çalışır?',
    'landing.faq_a5':
      'Üç rol vardır: Satış temsilcisi (teklif oluşturur), satış yöneticisi (onaylar/reddeder + tüm verileri görür), operasyon (katalog/fiyat yönetimi). Her kullanıcı sadece yetkili olduğu verileri görür ve işlem yapabilir.',
    'landing.faq_q6': 'Fiyat listesi ve katalog nasıl yüklenir?',
    'landing.faq_a6':
      'Excel (.xlsx), CSV veya PDF formatlarında toplu import desteği vardır. Sistem Honeywell parça kodlarını otomatik tanır. Fiyat geçerlilik tarihleri, para birimi ve indirim oranları da yüklenir.',

