    'landing.faq_label': 'FAQ',
    'landing.faq_title': 'Frequently asked questions',
    'landing.faq_q1': 'Are our emails secure?',
    'landing.faq_a1':
      'Yes. Credentials are encrypted with Fernet (AES-256). IMAP uses SSL/TLS. Data lives in PostgreSQL with RBAC. Audit trail captures every action.',
    'landing.faq_q2': 'What if the AI is wrong?',
    'landing.faq_a2':
      'Each parse includes a confidence score. Results below the threshold go to human review. Nothing auto-approves — a human always decides. Corrections improve future suggestions.',
    'landing.faq_q3': 'How long is setup?',
    'landing.faq_a3':
      'Typically one business day after mailbox connection, catalog, and price list import. Guided training included.',
    'landing.faq_q4': 'Will this break our current process?',
    'landing.faq_a4':
      'No. It sits beside your existing mail flow. Your inbox stays the same; the system reads copies (read-only IMAP). Feature flags support phased rollout.',
    'landing.faq_q5': 'How do approvals and permissions work?',
    'landing.faq_a5':
      'Three roles: rep (creates quotes), manager (approves/rejects + full visibility), operations (catalog/pricing). Users only act on data they are allowed to see.',
    'landing.faq_q6': 'How do we load price lists and catalogs?',
    'landing.faq_a6':
      'Bulk import from Excel (.xlsx), CSV, or PDF. Honeywell part codes are recognized automatically. Validity dates, currency, and discount tiers are supported.',

