type TranslationKey = keyof typeof translations.tr;
export type { TranslationKey };

export function t(key: TranslationKey, lang: string = 'tr'): string {
  const dict = (translations[lang as keyof typeof translations] || translations.tr) as Record<
    TranslationKey,
    string
  >;
  return dict[key] || translations.tr[key] || key;
}

